Here is the code for creating a simple web app with React, Node, and Express.js:

**Step 1: Create a new React app**

```bash
npx create-react-app my-app
cd my-app
```

**Step 2: Create a new Node and Express.js server**

```bash
mkdir server
cd server
npm init -y
npm install express
```

**Step 3: Create a new file for the server**

```bash
touch server.js
```

**Step 4: Write the server code**

```javascript
// server.js
const express = require('express');
const app = express();
const port = 3001;

app.use(express.json());

const dummyData = [
  { id: 1, name: 'John Doe', age: 30 },
  { id: 2, name: 'Jane Doe', age: 25 },
  { id: 3, name: 'Bob Smith', age: 40 },
];

app.get('/api/data', (req, res) => {
  res.json(dummyData);
});

app.post('/api/data', (req, res) => {
  const { name, age } = req.body;
  const newData = { id: dummyData.length + 1, name, age };
  dummyData.push(newData);
  res.json(newData);
});

app.listen(port, () => {
  console.log(`Server listening on port ${port}`);
});
```

**Step 5: Create a new file for the API client**

```bash
touch api-client.js
```

**Step 6: Write the API client code**

```javascript
// api-client.js
import axios from 'axios';

const apiClient = axios.create({
  baseURL: 'http://localhost:3001/api',
});

export const getData = async () => {
  const response = await apiClient.get('/data');
  return response.data;
};

export const postData = async (data) => {
  const response = await apiClient.post('/data', data);
  return response.data;
};
```

**Step 7: Update the React app to use the API client**

```bash
// src/App.js
import React, { useState, useEffect } from 'react';
import { getData, postData } from './api-client';

function App() {
  const [data, setData] = useState([]);
  const [name, setName] = useState('');
  const [age, setAge] = useState('');

  useEffect(() => {
    const fetchData = async () => {
      const data = await getData();
      setData(data);
    };
    fetchData();
  }, []);

  const handleSubmit = async (event) => {
    event.preventDefault();
    const newData = await postData({ name, age });
    setData([...data, newData]);
    setName('');
    setAge('');
  };

  return (
    <div>
      <h1>Dummy Data App</h1>
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          value={name}
          onChange={(event) => setName(event.target.value)}
          placeholder="Name"
        />
        <input
          type="number"
          value={age}
          onChange={(event) => setAge(event.target.value)}
          placeholder="Age"
        />
        <button type="submit">Add Data</button>
      </form>
      <ul>
        {data.map((item) => (
          <li key={item.id}>
            {item.name} ({item.age})
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
```

