        let drawableList = firstTwo.reversed().map({ $0.withRenderingMode(.alwaysTemplate) }).toArray()
        return StackedDrawables(layers: drawableList, iconScale: iconScale)
    }

    override func setNeedsLayout() {
        super.setNeedsLayout()
        if shouldPlaceIcons { placeIcons() } else { shouldPlaceIcons = true }
    }

